/**
 * `networkx.minimum_spanning_tree`, Kruskal's algorithm (the networkx default).
 */

import { Graph } from './graph.mjs';

/** Union-Find with path compression and union by rank. */
class UnionFind {
  constructor() {
    this._parent = new Map();
    this._rank = new Map();
  }

  find(x) {
    if (!this._parent.has(x)) {
      this._parent.set(x, x);
      this._rank.set(x, 0);
      return x;
    }
    let root = x;
    while (this._parent.get(root) !== root) root = this._parent.get(root);
    let walk = x;
    while (this._parent.get(walk) !== root) {
      const next = this._parent.get(walk);
      this._parent.set(walk, root);
      walk = next;
    }
    return root;
  }

  union(a, b) {
    const rootA = this.find(a);
    const rootB = this.find(b);
    if (rootA === rootB) return;
    const rankA = this._rank.get(rootA);
    const rankB = this._rank.get(rootB);
    if (rankA < rankB) {
      this._parent.set(rootA, rootB);
    } else if (rankA > rankB) {
      this._parent.set(rootB, rootA);
    } else {
      this._parent.set(rootB, rootA);
      this._rank.set(rootA, rankA + 1);
    }
  }
}

/**
 * Kruskal edges. `sorted()` in Python is stable and keys on the weight alone, so
 * equal-weight edges stay in `G.edges()` order — which is what decides the tree
 * when weights tie. Self-loops are always rejected, since both endpoints already
 * share a component.
 */
export function* kruskalEdges(G, weightKey = 'weight') {
  const edges = [...G.edges()].map(([u, v, data], index) => ({
    u,
    v,
    weight: data[weightKey] ?? 1,
    index,
  }));
  edges.sort((a, b) => (a.weight === b.weight ? a.index - b.index : a.weight - b.weight));

  const subtrees = new UnionFind();
  for (const { u, v, weight } of edges) {
    if (subtrees.find(u) !== subtrees.find(v)) {
      subtrees.union(u, v);
      yield [u, v, weight];
    }
  }
}

/** `nx.minimum_spanning_tree(G)`: every node of G, plus the Kruskal edges. */
export function minimumSpanningTree(G, weightKey = 'weight') {
  const tree = new Graph();
  for (const node of G.nodes()) tree.addNode(node);
  for (const [u, v, weight] of kruskalEdges(G, weightKey)) {
    tree.addEdge(u, v, { [weightKey]: weight });
  }
  return tree;
}

=== shortest_path ===
/**
 * Dijkstra shortest paths, following `networkx._dijkstra_multisource`.
 *
 * Two details drive exact output alignment:
 *  - The source starts at Python *int* `0`, while every edge weight is a float. So
 *    a zero-length result (source == target) prints as `0`, not `0.0`. Distances
 *    carry an `isFloat` tag to preserve that.
 *  - Relaxation is strict `<`, and the heap orders by (distance, insertion
 *    counter). Equal-cost paths therefore resolve to the one discovered first.
 */

import { Heap, byPriorityThenSequence } from '../python/heapq.mjs';

class NetworkXNoPath extends Error {}

/** A distance that remembers whether Python would hold an int or a float. */
function intZero() {
  return { value: 0, isFloat: false };
}

function add(distance, cost) {
  return { value: distance.value + cost, isFloat: true };
}

/**
 * Single-source Dijkstra to `target`. Returns the distance and the path built the
 * same way networkx does (`paths[u] = paths[v] + [u]`, overwritten only on strict
 * improvement).
 */
export function dijkstra(G, source, target, weightKey = 'weight') {
  if (!G.hasNode(source)) throw new NetworkXNoPath(`node ${source} not in graph`);

  const dist = new Map();
  const seen = new Map([[source, intZero()]]);
  const paths = new Map([[source, [source]]]);
  const fringe = new Heap(byPriorityThenSequence);
  let counter = 0;

  fringe.push({ priority: 0, sequence: counter++, node: source, distance: intZero() });

  while (fringe.size > 0) {
    const { node: v, distance: d } = fringe.pop();
    if (dist.has(v)) continue;
    dist.set(v, d);
    if (v === target) break;

    for (const [u, data] of G.adj(v)) {
      const cost = data[weightKey];
      if (cost === undefined) continue;
      const candidate = add(d, cost);
      const known = seen.get(u);
      if (dist.has(u)) continue;
      if (known === undefined || candidate.value < known.value) {
        seen.set(u, candidate);
        fringe.push({ priority: candidate.value, sequence: counter++, node: u, distance: candidate });
        paths.set(u, [...paths.get(v), u]);
      }
    }
  }

  if (!dist.has(target)) {
    throw new NetworkXNoPath(`No path between ${source} and ${target}.`);
  }
  return { length: dist.get(target), path: paths.get(target) };
}

/** `nx.dijkstra_path_length`: the tagged distance, so the caller can print it faithfully. */
export function dijkstraPathLength(G, source, target, weightKey = 'weight') {
  return dijkstra(G, source, target, weightKey).length;
}

/** `nx.dijkstra_path`. */
export function dijkstraPath(G, source, target, weightKey = 'weight') {
  return dijkstra(G, source, target, weightKey).path;
}
