/**
 * Connectivity: `networkx.is_connected` and `networkx.node_connectivity`.
 */

import { buildAuxiliaryNodeConnectivity, maximumFlowValue, sideA, sideB } from './flow.mjs';

/** `nx.is_connected`: a plain BFS from the first node reaches every node. */
export function isConnected(G) {
  const total = G.numberOfNodes();
  if (total === 0) {
    throw new Error('Connectivity is undefined for the null graph.');
  }
  const start = G.nodes().next().value;
  const seen = new Set([start]);
  const queue = [start];
  for (let head = 0; head < queue.length; head += 1) {
    for (const nbr of G.neighbors(queue[head])) {
      if (!seen.has(nbr)) {
        seen.add(nbr);
        queue.push(nbr);
      }
    }
  }
  return seen.size === total;
}

/**
 * `nx.local_node_connectivity(G, s, t)`: the number of internally node-disjoint
 * s-t paths, as a max flow from sB to tA on the split-node digraph.
 */
export function localNodeConnectivity(G, s, t, auxiliary = buildAuxiliaryNodeConnectivity(G)) {
  const source = sideB(auxiliary.mapping.get(s));
  const sink = sideA(auxiliary.mapping.get(t));
  return maximumFlowValue(auxiliary, source, sink);
}

/**
 * `nx.node_connectivity(G)` for an undirected graph, following networkx's search
 * exactly rather than computing textbook vertex connectivity:
 *
 *   - a disconnected graph is 0;
 *   - otherwise start from K = the minimum degree, taking the *first* minimum in
 *     node insertion order (and remember a self-loop adds 2 to a degree, so it can
 *     leave K above the graph's true connectivity);
 *   - lower K with the local connectivity of that node against each non-neighbour,
 *     then against each non-adjacent pair of its neighbours.
 */
export function nodeConnectivity(G) {
  if (!isConnected(G)) return 0;

  let v = null;
  let K = null;
  for (const [node, degree] of G.degrees()) {
    if (K === null || degree < K) {
      v = node;
      K = degree;
    }
  }

  const auxiliary = buildAuxiliaryNodeConnectivity(G);
  const neighbors = [...G.neighbors(v)];
  const neighborSet = new Set(neighbors);

  for (const w of G.nodes()) {
    if (w === v || neighborSet.has(w)) continue;
    K = Math.min(K, localNodeConnectivity(G, v, w, auxiliary));
  }

  for (let i = 0; i < neighbors.length; i += 1) {
    for (let j = i + 1; j < neighbors.length; j += 1) {
      const [x, y] = [neighbors[i], neighbors[j]];
      if (G.hasEdge(x, y)) continue;
      K = Math.min(K, localNodeConnectivity(G, x, y, auxiliary));
    }
  }

  return K;
}
=== flow ===
/**
 * Maximum flow on the auxiliary digraph used for node connectivity.
 *
 * `networkx.connectivity.build_auxiliary_node_connectivity` splits every node v
 * into vA -> vB with capacity 1 and turns each undirected edge {u, v} into the arcs
 * uB -> vA and vB -> uA (also capacity 1). A maximum flow from sB to tA then counts
 * internally node-disjoint s-t paths, because every interior node is throttled to
 * one unit by its own split arc.
 *
 * All capacities are 1, so Edmonds-Karp (BFS augmenting paths) is exact and the
 * value is independent of the search order.
 */

/** Split-node index scheme: node i occupies 2i (the "A" side) and 2i+1 (the "B" side). */
const sideA = (i) => 2 * i;
const sideB = (i) => 2 * i + 1;

export function buildAuxiliaryNodeConnectivity(G) {
  const mapping = new Map();
  for (const node of G.nodes()) mapping.set(node, mapping.size);

  // Assignment semantics, not accumulation: a repeated arc keeps capacity 1, which
  // matters for self-loops (they emit the same arc twice).
  const arcs = new Map();
  const addArc = (from, to) => arcs.set(`${from}>${to}`, [from, to]);

  for (const i of mapping.values()) addArc(sideA(i), sideB(i));
  for (const [u, v] of G.edges()) {
    addArc(sideB(mapping.get(u)), sideA(mapping.get(v)));
    addArc(sideB(mapping.get(v)), sideA(mapping.get(u)));
  }

  return { mapping, order: 2 * mapping.size, arcs: [...arcs.values()] };
}

/** Residual network held as paired arcs: arc `i` and its reverse `i ^ 1`. */
class FlowNetwork {
  constructor(order) {
    this._first = new Array(order).fill(-1);
    this._next = [];
    this._target = [];
    this._capacity = [];
  }

  addArc(from, to, capacity) {
    this._push(from, to, capacity);
    this._push(to, from, 0);
  }

  _push(from, to, capacity) {
    this._target.push(to);
    this._capacity.push(capacity);
    this._next.push(this._first[from]);
    this._first[from] = this._target.length - 1;
  }

  /** Max flow value from `source` to `sink`, one BFS augmentation at a time. */
  maximumFlowValue(source, sink) {
    if (source === sink) return Infinity;
    let value = 0;
    for (;;) {
      const cameFrom = new Array(this._first.length).fill(-1);
      cameFrom[source] = -2;
      const queue = [source];
      let head = 0;
      while (head < queue.length && cameFrom[sink] === -1) {
        const node = queue[head++];
        for (let arc = this._first[node]; arc !== -1; arc = this._next[arc]) {
          const to = this._target[arc];
          if (this._capacity[arc] > 0 && cameFrom[to] === -1) {
            cameFrom[to] = arc;
            queue.push(to);
          }
        }
      }
      if (cameFrom[sink] === -1) return value;

      let bottleneck = Infinity;
      for (let arc = cameFrom[sink]; arc !== -2; arc = cameFrom[this._target[arc ^ 1]]) {
        bottleneck = Math.min(bottleneck, this._capacity[arc]);
      }
      for (let arc = cameFrom[sink]; arc !== -2; arc = cameFrom[this._target[arc ^ 1]]) {
        this._capacity[arc] -= bottleneck;
        this._capacity[arc ^ 1] += bottleneck;
      }
      value += bottleneck;
    }
  }
}

export function maximumFlowValue(auxiliary, source, sink) {
  const network = new FlowNetwork(auxiliary.order);
  for (const [from, to] of auxiliary.arcs) network.addArc(from, to, 1);
  return network.maximumFlowValue(source, sink);
}

